INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-162',unit_id,'quiz-topic-neuro-ap1','Que lobos cerebrais repousam na fossa craniana anterior?',NULL,'A fossa craniana anterior é formada pelos ossos frontal, etmóide e esfenóide e suporta os <strong>lobos frontais</strong> dos hemisférios cerebrais. O pavimento é constituído pela parte orbitária do frontal, pela lâmina crivosa e crista galli do etmóide e pelas asas menores, jugo esfenoidal e sulco pré-quiasmático do esfenóide.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
