INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-165',unit_id,'quiz-topic-neuro-ap1','Que fibras atravessam os pequenos buracos da lâmina crivosa?',NULL,'A lâmina crivosa do etmóide é uma lâmina óssea perfurada que se estende na linha média entre as partes orbitárias do frontal e fica deprimida relativamente a estas, formando parte do teto da cavidade nasal. As <strong>fibras dos nervos olfativos</strong> passam da mucosa nasal para o bulbo olfativo através dos numerosos pequenos buracos da lâmina crivosa. Anteriormente, a crista galli projeta-se superiormente entre os hemisférios cerebrais e dá inserção à foice do cérebro.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
