INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-166',unit_id,'quiz-topic-neuro-ap1','Que pequeno buraco pode comunicar mucosa nasal e seio sagital superior?',NULL,'Habitualmente, o <strong>buraco cego</strong> é uma pequena depressão de fundo cego resultante da involução de um divertículo da dura-máter que, durante o desenvolvimento, se prolonga até à columela; no adulto, ocasionalmente pode transmitir uma veia entre a mucosa nasal e o seio sagital superior. A ausência de encerramento do buraco cego pode associar-se a quistos dermóides nasais e encefalocelos nasoetmoidais em crianças.<p><small>Gray’s Anatomy, 42.ª ed., p. 565.</small></p>','hard','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-166-answer','quiz-neuro-ap1-166','Buraco cego',1,1);
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-166-incorrect','quiz-neuro-ap1-166','Resposta não correspondente',2,0);
INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-167',unit_id,'quiz-topic-neuro-ap1','Que estrutura óssea une as duas asas menores do esfenóide?',NULL,'Posteriormente, articula-se lateralmente com o bordo anterior da asa menor do esfenóide e medialmente com o <strong>jugo esfenoidal</strong>. O jugo esfenoidal ou planum sphenoidale é uma superfície plana da face superior do esfenóide que une as duas asas menores. O limbo esfenoidal é uma crista proeminente do corpo do esfenóide que forma o bordo posterior do jugo e o bordo anterior do sulco pré-quiasmático.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-167-answer','quiz-neuro-ap1-167','Jugo esfenoidal',1,1);
