INSERT INTO quiz_questions (id,curricular_unit_id,topic_id,prompt,image_url,explanation,difficulty,status,published_at,published_by,created_by,updated_by,created_at,updated_at) SELECT 'quiz-neuro-ap1-174',unit_id,'quiz-topic-neuro-ap1','Que estrutura separa as duas raízes da asa menor?',NULL,'A extremidade medial da asa menor constitui a apófise clinóide anterior. A asa menor e a apófise clinóide anterior ligam-se ao corpo do esfenóide por duas raízes separadas pelo <strong>canal óptico</strong>. A raiz anterior, larga e achatada, forma o teto do canal óptico e continua-se com o jugo esfenoidal; a raiz posterior, menor e mais espessa, também designada pilar óptico, liga-se ao corpo do esfenóide junto da face lateral do bordo posterior do sulco pré-quiasmático ou do tubérculo da sela.<p><small>Gray’s Anatomy, 42.ª ed., p. 566.</small></p>','medium','published',unixepoch()*1000,actor_id,actor_id,actor_id,unixepoch()*1000,unixepoch()*1000 FROM _seed_neuro_ap1_context WHERE true ON CONFLICT(id) DO UPDATE SET curricular_unit_id=excluded.curricular_unit_id,topic_id=excluded.topic_id,prompt=excluded.prompt,image_url=NULL,explanation=excluded.explanation,difficulty=excluded.difficulty,status='published',published_at=COALESCE(quiz_questions.published_at,excluded.published_at),published_by=COALESCE(quiz_questions.published_by,excluded.published_by),archived_at=NULL,archived_by=NULL,deleted_at=NULL,deleted_by=NULL,updated_by=excluded.updated_by,updated_at=excluded.updated_at;
INSERT INTO quiz_question_options (id,question_id,option_text,position,is_correct) VALUES ('quiz-neuro-ap1-174-answer','quiz-neuro-ap1-174','Canal óptico',1,1);
